mapper.select:
select

from CHB_SUB_CHECK_ITEM_RULE
where CLASS_ID = #{classId,jdbcType=VARCHAR}
and ITEM_RULE_NO = #{itemRuleNo,jdbcType=DECIMAL}

mapper.delete:
delete from CHB_SUB_CHECK_ITEM_RULE
where CLASS_ID = #{classId,jdbcType=VARCHAR}
  and ITEM_RULE_NO = #{itemRuleNo,jdbcType=DECIMAL}

mapper.update:
update CHB_SUB_CHECK_ITEM_RULE
set ITEM_CODE = #{itemCode,jdbcType=VARCHAR},
    ITEM_NAME = #{itemName,jdbcType=VARCHAR},
    CHECK_RULE_ID = #{checkRuleId,jdbcType=VARCHAR},
    CHECK_RULE_PARA = #{checkRulePara,jdbcType=VARCHAR},
    REMARK = #{remark,jdbcType=VARCHAR}
where CLASS_ID = #{classId,jdbcType=VARCHAR}
  and ITEM_RULE_NO = #{itemRuleNo,jdbcType=DECIMAL}
